<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_module('reports');require_once ROOT_PATH.'/includes/reporting.php';$format=$_GET['format']??'csv';$type=$_GET['type']??'budget';$from=$_GET['from']??date('Y-01-01');$to=$_GET['to']??date('Y-m-d');$dept=(int)($_GET['department_id']??0);$report=build_report($type,$from,$to,$dept);$rows=$report['rows'];$filename=preg_replace('/[^A-Za-z0-9_-]/','_',strtolower($report['title'])).'_'.date('Ymd_His');
try{db()->prepare('INSERT INTO reports(report_type,date_from,date_to,generated_by,export_format) VALUES(?,?,?,?,?)')->execute([$type,$from,$to,current_user()['id'],$format]);}catch(Throwable $e){}log_activity('EXPORT','Reports',$report['title'].' as '.$format);
if($format==='excel'){header('Content-Type: application/vnd.ms-excel; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$filename.'.xls"');echo "\xEF\xBB\xBF";echo '<table border="1">';if($rows){echo '<tr>';foreach(array_keys($rows[0]) as $h)echo '<th>'.e($h).'</th>';echo '</tr>';foreach($rows as $r){echo '<tr>';foreach($r as $v)echo '<td>'.e((string)$v).'</td>';echo '</tr>';}}echo '</table>';exit;}
header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$filename.'.csv"');$out=fopen('php://output','w');fprintf($out, chr(0xEF).chr(0xBB).chr(0xBF));if($rows){fputcsv($out,array_keys($rows[0]));foreach($rows as $r)fputcsv($out,$r);}fclose($out);exit;
